/**
 * Rôle : Collecte sélective et sécurisée des nœuds texte et attributs traduisibles du DOM (et des Shadow DOM ouverts).
 * Entrées : Nœud racine (Document, Element, ShadowRoot ou Node ajouté par mutation).
 * Sorties : Tableau de cibles TranslatableTarget (nœud Text ou attribut d'Element).
 * Limites : Ignore strictement <script>, <style>, <noscript>, <textarea>, <code>, <pre>, <svg>, contenteditable, translate="no", .notranslate, ainsi que les <input type="password">, les champs à autocomplete sensible ("cc-", "one-time-code", "password") et la valeur saisie des <input>.
 */

export type TranslatableAttr =
  | "placeholder"
  | "title"
  | "aria-label"
  | "aria-placeholder"
  | "data-placeholder"
  | "alt"
  | "label"
  | "value";

export type TranslatableTarget =
  | { kind: "text"; node: Text }
  | { kind: "attr"; element: Element; attr: TranslatableAttr };

export const BADGE_HOST_ID = "linguafin-badge-host";

const IGNORED_TAGS = new Set<string>([
  "SCRIPT",
  "STYLE",
  "NOSCRIPT",
  "TEXTAREA",
  "CODE",
  "PRE",
  "SVG",
  "CANVAS",
  "IFRAME",
  "OBJECT",
  "EMBED"
]);

const BUTTON_INPUT_TYPES = new Set<string>(["button", "submit", "reset"]);
const SENSITIVE_AUTOCOMPLETE_PATTERNS = ["cc-", "one-time-code", "password"];
const STANDARD_ATTRS: readonly TranslatableAttr[] = [
  "placeholder",
  "title",
  "aria-label",
  "aria-placeholder",
  "data-placeholder",
  "alt",
  "label"
];

/**
 * Vérifie si un élément (ou l'un de ses ancêtres) doit être intégralement exclu de la traduction.
 */
export function isIgnoredElement(el: Element | null): boolean {
  let current: Element | null = el;
  while (current) {
    if (current.id === BADGE_HOST_ID) {
      return true;
    }

    const tag = current.tagName?.toUpperCase() ?? "";
    if (IGNORED_TAGS.has(tag)) {
      return true;
    }

    // Exclusion des éléments SVG (même si tagName est en minuscules dans un espace de noms SVG)
    if (current.namespaceURI === "http://www.w3.org/2000/svg") {
      return true;
    }

    // Exclusion des zones éditables par l'utilisateur (contenteditable)
    const ceAttr = current.getAttribute("contenteditable");
    if (
      (current as HTMLElement).isContentEditable ||
      (ceAttr !== null && ceAttr.toLowerCase() !== "false")
    ) {
      return true;
    }

    // Respect des conventions standard du web : translate="no" et class="notranslate"
    const translateAttr = current.getAttribute("translate");
    if (translateAttr && translateAttr.toLowerCase() === "no") {
      return true;
    }
    if (current.classList && current.classList.contains("notranslate")) {
      return true;
    }

    // Vérification de sécurité sur les éléments <input>
    if (tag === "INPUT" && isSensitiveInput(current as HTMLInputElement)) {
      return true;
    }

    current = current.parentElement;
  }
  return false;
}

/**
 * Indique si un champ <input> est sensible (mot de passe, carte bancaire, code OTP, champ caché).
 * Aucun attribut ni contenu d'un tel champ ne doit jamais être lu ou modifié.
 */
export function isSensitiveInput(input: HTMLInputElement): boolean {
  const typeAttr = (input.getAttribute("type") ?? input.type ?? "text").toLowerCase().trim();
  if (typeAttr === "password" || typeAttr === "hidden") {
    return true;
  }

  const autoComplete = (input.getAttribute("autocomplete") ?? "").toLowerCase();
  if (autoComplete) {
    for (const pattern of SENSITIVE_AUTOCOMPLETE_PATTERNS) {
      if (autoComplete.includes(pattern)) {
        return true;
      }
    }
  }

  return false;
}

/**
 * Collecte les attributs traduisibles d'un élément unique non ignoré.
 */
function collectElementAttributes(el: Element, out: TranslatableTarget[]): void {
  const tag = el.tagName?.toUpperCase() ?? "";

  if (tag === "INPUT") {
    const input = el as HTMLInputElement;
    if (isSensitiveInput(input)) {
      return;
    }
    const typeAttr = (input.getAttribute("type") ?? input.type ?? "text").toLowerCase().trim();
    if (BUTTON_INPUT_TYPES.has(typeAttr)) {
      // Seuls les <input type="button|submit|reset"> ont leur attribut value traduit
      for (const attr of ["value", "title", "aria-label"] as const) {
        const val = input.getAttribute(attr);
        if (val && val.trim().length > 0) {
          out.push({ kind: "attr", element: input, attr });
        }
      }
    } else {
      // Pour les autres <input> non sensibles : JAMAIS toucher value, uniquement placeholder/title/aria-label
      for (const attr of ["placeholder", "title", "aria-label"] as const) {
        const val = input.getAttribute(attr);
        if (val && val.trim().length > 0) {
          out.push({ kind: "attr", element: input, attr });
        }
      }
    }
    return;
  }

  for (const attr of STANDARD_ATTRS) {
    const val = el.getAttribute(attr);
    if (val && val.trim().length > 0) {
      out.push({ kind: "attr", element: el, attr });
    }
  }
}

/**
 * Parcourt un sous-arbre DOM (y compris les ShadowRoot ouverts) à l'aide de TreeWalker et retourne toutes les cibles traduisibles.
 */
export function collectTranslatableTargets(root: Node): TranslatableTarget[] {
  const targets: TranslatableTarget[] = [];
  const doc = root.ownerDocument ?? (root as Document);
  if (!doc || typeof doc.createTreeWalker !== "function") {
    return targets;
  }

  function walkRoot(currentRoot: Node): void {
    if (currentRoot.nodeType === Node.TEXT_NODE) {
      const textNode = currentRoot as Text;
      if (
        textNode.nodeValue &&
        textNode.nodeValue.trim().length > 0 &&
        !isIgnoredElement(textNode.parentElement)
      ) {
        targets.push({ kind: "text", node: textNode });
      }
      return;
    }

    if (currentRoot.nodeType === Node.ELEMENT_NODE) {
      const rootEl = currentRoot as Element;
      if (isIgnoredElement(rootEl)) {
        return;
      }
      if (rootEl.tagName?.toUpperCase() !== "INPUT") {
        collectElementAttributes(rootEl, targets);
      } else {
        collectElementAttributes(rootEl, targets);
        return;
      }
      if (rootEl.shadowRoot) {
        walkRoot(rootEl.shadowRoot);
      }
    }

    const walker = doc.createTreeWalker(
      currentRoot,
      NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT,
      {
        acceptNode(node: Node): number {
          if (node.nodeType === Node.ELEMENT_NODE) {
            const el = node as Element;
            if (isIgnoredElement(el)) {
              return NodeFilter.FILTER_REJECT;
            }
            return NodeFilter.FILTER_ACCEPT;
          }
          if (node.nodeType === Node.TEXT_NODE) {
            const parent = node.parentElement;
            if (isIgnoredElement(parent)) {
              return NodeFilter.FILTER_REJECT;
            }
            if (!node.nodeValue || node.nodeValue.trim().length === 0) {
              return NodeFilter.FILTER_SKIP;
            }
            return NodeFilter.FILTER_ACCEPT;
          }
          return NodeFilter.FILTER_SKIP;
        }
      }
    );

    let currentNode = walker.nextNode();
    while (currentNode) {
      if (currentNode.nodeType === Node.ELEMENT_NODE) {
        const el = currentNode as Element;
        collectElementAttributes(el, targets);
        if (el.shadowRoot) {
          walkRoot(el.shadowRoot);
        }
      } else if (currentNode.nodeType === Node.TEXT_NODE) {
        targets.push({ kind: "text", node: currentNode as Text });
      }
      currentNode = walker.nextNode();
    }
  }

  walkRoot(root);
  return targets;
}

/**
 * Échantillonne jusqu'à `maxNodes` textes visibles significatifs pour la détection de la langue de la page.
 * Inclut aussi les libellés courts (1 à 2 mots) fréquents dans les tableaux de bord React / Next.js / Angular.
 */
export function collectPageSampleTexts(root: Node, maxNodes = 400): string[] {
  const targets = collectTranslatableTargets(root);
  const samples: string[] = [];

  for (const target of targets) {
    if (samples.length >= maxNodes) {
      break;
    }
    const raw =
      target.kind === "text"
        ? target.node.nodeValue ?? ""
        : target.element.getAttribute(target.attr) ?? "";
    const trimmed = raw.trim();
    if (trimmed.length >= 2) {
      samples.push(trimmed);
    }
  }

  return samples;
}

