/**
 * Rôle : Observation des mutations DOM (MutationObserver) en temps réel (formulaires dynamiques, étapes sans rechargement, modales, messages de validation)
 *        avec verrou anti-boucle (applying + takeRecords), debounce rapide et collecte incrémentale des nœuds/attributs ajoutés, modifiés ou révélés.
 * Entrées : Élément racine à observer et fonction de rappel onTargetsToTranslate(targets).
 * Sorties : Déclenchement par lots sur les nœuds mutés par le site hôte, sans jamais reboucler sur les écritures de l'extension ni perdre les mutations du site.
 * Limites : Ne traverse jamais le document complet lors d'une mutation locale.
 */

import {
  collectTranslatableTargets,
  isIgnoredElement,
  type TranslatableAttr,
  type TranslatableTarget
} from "./dom-walker.js";

const TRANSLATABLE_ATTRIBUTES: TranslatableAttr[] = [
  "placeholder",
  "title",
  "aria-label",
  "aria-placeholder",
  "data-placeholder",
  "alt",
  "label",
  "value"
];

/**
 * Attributs d'état ou de visibilité couramment utilisés par les formulaires multi-étapes,
 * onglets, champs conditionnels et alertes de validation (React, Next.js, Angular, Vue, JS).
 */
const STATE_ATTRIBUTES: readonly string[] = [
  "class",
  "style",
  "hidden",
  "aria-hidden",
  "open",
  "data-state",
  "aria-expanded",
  "aria-invalid",
  "disabled"
];

const ALL_OBSERVED_ATTRIBUTES: string[] = [
  ...TRANSLATABLE_ATTRIBUTES,
  ...STATE_ATTRIBUTES
];

export class DomTranslationObserver {
  private observer: MutationObserver | null = null;
  private applying = false;
  private debounceTimer: ReturnType<typeof setTimeout> | null = null;
  private pendingNodes = new Set<Node>();
  private pendingAttrs = new Map<Element, Set<TranslatableAttr>>();
  private readonly debounceMs: number;
  private readonly onTargetsMutated: (targets: TranslatableTarget[]) => void;

  constructor(
    onTargetsMutated: (targets: TranslatableTarget[]) => void,
    debounceMs = 45
  ) {
    this.onTargetsMutated = onTargetsMutated;
    this.debounceMs = debounceMs;
  }

  /**
   * Démarre l'observation sur la racine spécifiée (typiquement document.documentElement).
   */
  public start(root: Node = document.documentElement): void {
    this.stop();
    this.observer = new MutationObserver((records) => {
      this.handleMutations(records);
    });
    this.observer.observe(root, {
      subtree: true,
      childList: true,
      characterData: true,
      attributes: true,
      attributeFilter: ALL_OBSERVED_ATTRIBUTES
    });
  }

  /**
   * Arrête l'observation et nettoie les files d'attente.
   */
  public stop(): void {
    if (this.debounceTimer !== null) {
      clearTimeout(this.debounceTimer);
      this.debounceTimer = null;
    }
    if (this.observer) {
      this.observer.takeRecords();
      this.observer.disconnect();
      this.observer = null;
    }
    this.pendingNodes.clear();
    this.pendingAttrs.clear();
  }

  /**
   * Exécute une opération d'écriture DOM sous verrou anti-boucle :
   * 1. Récupère et traite d'abord toute mutation du site en attente dans la file du MutationObserver (pour ne jamais perdre un changement de formulaire).
   * 2. Exécute l'écriture de l'extension sous applying = true.
   * 3. Purge uniquement les enregistrements produits par cette écriture.
   */
  public withApplying<T>(fn: () => T): T {
    if (this.observer && !this.applying) {
      const priorSiteRecords = this.observer.takeRecords();
      if (priorSiteRecords.length > 0) {
        this.handleMutations(priorSiteRecords);
      }
    }
    this.applying = true;
    try {
      return fn();
    } finally {
      if (this.observer) {
        this.observer.takeRecords();
      }
      this.applying = false;
    }
  }

  private handleMutations(records: MutationRecord[]): void {
    if (this.applying) {
      return;
    }

    for (const record of records) {
      if (record.type === "childList") {
        record.addedNodes.forEach((node) => {
          if (node.nodeType === Node.ELEMENT_NODE && isIgnoredElement(node as Element)) {
            return;
          }
          if (node.nodeType === Node.TEXT_NODE && isIgnoredElement(node.parentElement)) {
            return;
          }
          this.pendingNodes.add(node);
        });
      } else if (record.type === "characterData") {
        const target = record.target;
        if (target.nodeType === Node.TEXT_NODE && !isIgnoredElement(target.parentElement)) {
          this.pendingNodes.add(target);
        }
      } else if (record.type === "attributes") {
        const el = record.target as Element;
        const attrName = record.attributeName;
        if (!el || el.nodeType !== Node.ELEMENT_NODE || !attrName || isIgnoredElement(el)) {
          continue;
        }
        if (TRANSLATABLE_ATTRIBUTES.includes(attrName as TranslatableAttr)) {
          let attrSet = this.pendingAttrs.get(el);
          if (!attrSet) {
            attrSet = new Set<TranslatableAttr>();
            this.pendingAttrs.set(el, attrSet);
          }
          attrSet.add(attrName as TranslatableAttr);
        } else if (STATE_ATTRIBUTES.includes(attrName)) {
          // Un élément (ex. étape de formulaire, champ conditionnel ou alerte d'erreur) a changé d'état ou de visibilité
          this.pendingNodes.add(el);
        }
      }
    }

    if (this.pendingNodes.size === 0 && this.pendingAttrs.size === 0) {
      return;
    }

    if (this.debounceTimer !== null) {
      clearTimeout(this.debounceTimer);
    }

    this.debounceTimer = setTimeout(() => {
      this.flushPending();
    }, this.debounceMs);
  }

  private flushPending(): void {
    this.debounceTimer = null;
    const nodes = [...this.pendingNodes];
    const attrs = [...this.pendingAttrs.entries()];
    this.pendingNodes.clear();
    this.pendingAttrs.clear();

    const collected: TranslatableTarget[] = [];
    const seenTextNodes = new Set<Text>();

    for (const node of nodes) {
      if (!node.isConnected) {
        continue;
      }
      const subTargets = collectTranslatableTargets(node);
      for (const t of subTargets) {
        if (t.kind === "text") {
          if (!seenTextNodes.has(t.node)) {
            seenTextNodes.add(t.node);
            collected.push(t);
          }
        } else {
          collected.push(t);
        }
      }
    }

    for (const [el, attrSet] of attrs) {
      if (!el.isConnected || isIgnoredElement(el)) {
        continue;
      }
      for (const attr of attrSet) {
        const val = el.getAttribute(attr);
        if (val && val.trim().length > 0) {
          collected.push({ kind: "attr", element: el, attr });
        }
      }
    }

    if (collected.length > 0) {
      this.onTargetsMutated(collected);
    }
  }
}
