/**
 * Rôle : Lecture, écriture et écoute des réglages utilisateur dans browser.storage.local (Section 5.8).
 * Entrées : Modifications partielles de réglages ou nom d'hôte courant.
 * Sorties : Objet Settings complet avec valeurs par défaut sécurisées.
 * Limites : Résiste à l'invalidation du contexte d'extension ("Extension context invalidated") lors du rechargement de l'extension.
 */

import type { LangCode } from "../core/types.js";
import { browser, isExtensionContextValid } from "./ext.js";

export interface Settings {
  enabledHosts: string[];
  mode: "auto" | "manual";
  targetLang: LangCode;
  showBadge: boolean;
  remoteEnabled: boolean;
  remoteUrl: string;
  modelServerEnabled?: boolean;
  modelServerUrl?: string;
  modelServerApiKey?: string;
  debug: boolean;
  v?: number;
}

export const STORAGE_KEY = "linguafin_settings";
const CURRENT_SETTINGS_VERSION = 2;

export const DEFAULT_SETTINGS: Readonly<Settings> = {
  enabledHosts: ["*"],
  mode: "auto",
  targetLang: "en",
  showBadge: true,
  remoteEnabled: false,
  remoteUrl: "",
  modelServerEnabled: false,
  modelServerUrl: "",
  modelServerApiKey: "",
  debug: false,
  v: CURRENT_SETTINGS_VERSION
};

/**
 * Lit les réglages depuis browser.storage.local en complétant avec les valeurs par défaut.
 */
export async function getSettings(): Promise<Settings> {
  if (!isExtensionContextValid()) {
    return { ...DEFAULT_SETTINGS, enabledHosts: [...DEFAULT_SETTINGS.enabledHosts] };
  }
  try {
    const raw = await browser.storage.local.get(STORAGE_KEY);
    const stored = raw?.[STORAGE_KEY] as Partial<Settings> | undefined;
    if (!stored || typeof stored !== "object") {
      return { ...DEFAULT_SETTINGS, enabledHosts: [...DEFAULT_SETTINGS.enabledHosts] };
    }
    let enabledHosts = Array.isArray(stored.enabledHosts)
      ? stored.enabledHosts.filter((h): h is string => typeof h === "string")
      : [...DEFAULT_SETTINGS.enabledHosts];

    // Migration automatique depuis la v1 : active le joker "*" pour tous les sites de test
    if (stored.v !== CURRENT_SETTINGS_VERSION && !enabledHosts.includes("*")) {
      enabledHosts = ["*", ...enabledHosts];
    }

    return {
      enabledHosts,
      mode: stored.mode === "manual" ? "manual" : "auto",
      targetLang: typeof stored.targetLang === "string" && stored.targetLang ? stored.targetLang : "en",
      showBadge: typeof stored.showBadge === "boolean" ? stored.showBadge : true,
      remoteEnabled: typeof stored.remoteEnabled === "boolean" ? stored.remoteEnabled : false,
      remoteUrl: typeof stored.remoteUrl === "string" ? stored.remoteUrl.trim() : "",
      modelServerEnabled: typeof stored.modelServerEnabled === "boolean" ? stored.modelServerEnabled : false,
      modelServerUrl: typeof stored.modelServerUrl === "string" ? stored.modelServerUrl.trim() : "",
      modelServerApiKey: typeof stored.modelServerApiKey === "string" ? stored.modelServerApiKey.trim() : "",
      debug: typeof stored.debug === "boolean" ? stored.debug : false,
      v: CURRENT_SETTINGS_VERSION
    };
  } catch {
    return { ...DEFAULT_SETTINGS, enabledHosts: [...DEFAULT_SETTINGS.enabledHosts] };
  }
}

/**
 * Met à jour partiellement les réglages dans browser.storage.local.
 */
export async function updateSettings(patch: Partial<Settings>): Promise<Settings> {
  const current = await getSettings();
  const next: Settings = {
    ...current,
    ...patch,
    enabledHosts: patch.enabledHosts ? [...new Set(patch.enabledHosts)] : current.enabledHosts,
    v: CURRENT_SETTINGS_VERSION
  };
  if (isExtensionContextValid()) {
    try {
      await browser.storage.local.set({ [STORAGE_KEY]: next });
    } catch {
      // Ignorer silencieusement si le contexte d'extension vient d'être rechargé
    }
  }
  return next;
}

/**
 * Vérifie si un nom d'hôte (location.hostname) figure dans la liste d'autorisation enabledHosts.
 * Supporte le joker "*" (tous les sites activés par défaut) et l'exclusion explicite "!hostname".
 */
export function isHostEnabled(hostname: string, settings: Settings): boolean {
  if (!hostname) {
    return false;
  }
  const normalized = hostname.trim().toLowerCase();
  const list = settings.enabledHosts.map((h) => h.trim().toLowerCase());
  if (list.includes(`!${normalized}`)) {
    return false;
  }
  return list.includes(normalized) || list.includes("*");
}

/**
 * Abonne un écouteur aux changements de réglages dans storage.onChanged.
 */
export function onSettingsChanged(callback: (newSettings: Settings) => void): () => void {
  if (!isExtensionContextValid()) {
    return () => {};
  }
  const listener = (
    changes: Record<string, { oldValue?: unknown; newValue?: unknown }>,
    areaName: string
  ) => {
    if (!isExtensionContextValid()) {
      return;
    }
    if (areaName === "local" && STORAGE_KEY in changes) {
      void getSettings().then(callback).catch(() => {});
    }
  };
  try {
    browser.storage.onChanged.addListener(listener);
  } catch {
    return () => {};
  }
  return () => {
    if (!isExtensionContextValid()) {
      return;
    }
    try {
      browser.storage.onChanged.removeListener(listener);
    } catch {
      // Ignorer si le contexte d'extension a été invalidé
    }
  };
}
