/**
 * Rôle : Typage des messages échangés entre la popup, le content script et le script d'arrière-plan optionnel (Section 5.8).
 * Entrées : Aucune (module de types et gardes de type).
 * Sorties : Interfaces de requêtes et de réponses pour browser.tabs.sendMessage et browser.runtime.sendMessage.
 * Limites : Ne contient jamais de données personnelles ou financières brutes lors d'appels distants.
 */

import type { LangCode, LanguageValidationStatus } from "../core/types.js";

export type ContentMessageType =
  | "GET_STATUS"
  | "TOGGLE_VIEW"
  | "RETRANSLATE"
  | "REMOTE_TRANSLATE"
  | "GOOGLE_TRANSLATE"
  | "MODEL_SERVER_TRANSLATE";

export interface GetStatusMessage {
  type: "GET_STATUS";
}

export interface ToggleViewMessage {
  type: "TOGGLE_VIEW";
}

export interface RetranslateMessage {
  type: "RETRANSLATE";
}

export interface RemoteTranslateMessage {
  type: "REMOTE_TRANSLATE";
  payload: {
    protectedText: string;
    src: LangCode;
    tgt: LangCode;
    remoteUrl: string;
  };
}

export interface GoogleTranslateMessage {
  type: "GOOGLE_TRANSLATE";
  payload: {
    protectedText: string;
    src: LangCode | "auto";
    tgt: LangCode;
  };
}

export interface ModelServerTranslateMessage {
  type: "MODEL_SERVER_TRANSLATE";
  payload: {
    protectedText: string;
    src: LangCode | "auto";
    tgt: LangCode;
    serverUrl: string;
    apiKey?: string;
    critical?: boolean;
  };
}

export type ExtensionMessage =
  | GetStatusMessage
  | ToggleViewMessage
  | RetranslateMessage
  | RemoteTranslateMessage
  | GoogleTranslateMessage
  | ModelServerTranslateMessage;

export interface ContentStatusResponse {
  enabled: boolean;
  host: string;
  pageLang: LangCode | "unknown";
  pageConfidence: number;
  targetLang: LangCode;
  targetLangStatus: LanguageValidationStatus;
  translatedCount: number;
  fallbackCount: number;
  unchangedCount: number;
  translatedView: boolean;
}

export interface RemoteTranslateResponse {
  ok: boolean;
  translatedText?: string;
  error?: string;
}

export function isExtensionMessage(msg: unknown): msg is ExtensionMessage {
  if (!msg || typeof msg !== "object") {
    return false;
  }
  const t = (msg as { type?: unknown }).type;
  return (
    t === "GET_STATUS" ||
    t === "TOGGLE_VIEW" ||
    t === "RETRANSLATE" ||
    t === "REMOTE_TRANSLATE" ||
    t === "GOOGLE_TRANSLATE" ||
    t === "MODEL_SERVER_TRANSLATE"
  );
}

