/**
 * Rôle : Chargement, normalisation et compilation des entrées du lexique (exactes et gabarits à slots) en structures de recherche rapide.
 * Entrées : Tableau d'entrées LexiconEntry (depuis lexicon.json) et liste des langues LanguageInfo (depuis languages.json).
 * Sorties : Objet CompiledLexicon contenant les tables de correspondance exacte et les expressions régulières de gabarits triées par spécificité décroissante.
 * Limites : Ne fait jamais de découpage mot à mot ; seuls les concepts entiers ou gabarits explicites sont compilés.
 */

import languagesData from "./languages.json" with { type: "json" };
import lexiconData from "./lexicon.json" with { type: "json" };
import type { LangCode, LanguageInfo, LexiconEntry } from "../core/types.js";

export interface CompiledTemplate {
  entry: LexiconEntry;
  srcLang: LangCode;
  regex: RegExp;
  slotNames: string[];
  literalLength: number;
}

export interface CompiledLexicon {
  entries: LexiconEntry[];
  languages: LanguageInfo[];
  exactMap: Map<LangCode, Map<string, LexiconEntry[]>>;
  templatesByLang: Map<LangCode, CompiledTemplate[]>;
}

const SLOT_REGEX = /\{([a-zA-Z0-9_]+)\}/g;

/**
 * Normalise une chaîne pour la correspondance exacte (Section 5.4) :
 * - trim
 * - espaces insécables (U+00A0, U+202F) -> espace standard
 * - apostrophes typographiques (’, ‘) -> apostrophe droite (')
 * - espaces multiples -> un seul espace
 * - mise en minuscules
 */
export function normalizeLexiconText(text: string): string {
  return text
    .replace(/[\u00A0\u202F]/g, " ")
    .replace(/['’‘`]/g, "'")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

/**
 * Extrait la liste ordonnée des noms de slots "{slot}" présents dans un texte de gabarit.
 */
export function extractSlots(templateText: string): string[] {
  const slots: string[] = [];
  const regex = new RegExp(SLOT_REGEX.source, "g");
  let match: RegExpExecArray | null;
  while ((match = regex.exec(templateText)) !== null) {
    slots.push(match[1]);
  }
  return slots;
}

/**
 * Échappe un segment littéral de gabarit pour en faire un motif RegExp tolérant aux espaces insécables et apostrophes typographiques.
 */
function escapeLiteralForTemplateRegex(literal: string): string {
  const normalized = literal
    .replace(/[\u00A0\u202F]/g, " ")
    .replace(/['’‘`]/g, "'")
    .replace(/\s+/g, " ");

  let pattern = "";
  for (let i = 0; i < normalized.length; i += 1) {
    const ch = normalized[i];
    if (ch === " ") {
      // Si l'espace précède un signe de ponctuation double (: ; ! ?), le rendre optionnel ou multiple
      const next = normalized[i + 1];
      if (next === ":" || next === ";" || next === "!" || next === "?") {
        pattern += "[\\s\\u00A0\\u202F]*";
      } else {
        pattern += "[\\s\\u00A0\\u202F]+";
      }
    } else if (ch === "'") {
      pattern += "['’‘`]";
    } else if (/[.*+?^${}()|[\]\\]/.test(ch)) {
      pattern += `\\${ch}`;
    } else {
      pattern += ch;
    }
  }
  return pattern;
}

/**
 * Compile une chaîne de gabarit contenant au moins un {slot} en expression régulière.
 */
export function compileTemplate(entry: LexiconEntry, srcLang: LangCode, templateStr: string): CompiledTemplate {
  const trimmed = templateStr.trim();
  const slotNames: string[] = [];
  let literalLength = 0;
  let regexParts = "^[\\s\\u00A0\\u202F]*";

  let lastIndex = 0;
  const regex = new RegExp(SLOT_REGEX.source, "g");
  let match: RegExpExecArray | null;

  while ((match = regex.exec(trimmed)) !== null) {
    const literalBefore = trimmed.slice(lastIndex, match.index);
    literalLength += normalizeLexiconText(literalBefore).length;
    regexParts += escapeLiteralForTemplateRegex(literalBefore);

    slotNames.push(match[1]);
    regexParts += "(.+?)";
    lastIndex = match.index + match[0].length;
  }

  const literalAfter = trimmed.slice(lastIndex);
  literalLength += normalizeLexiconText(literalAfter).length;
  regexParts += escapeLiteralForTemplateRegex(literalAfter);
  regexParts += "[\\s\\u00A0\\u202F]*$";

  return {
    entry,
    srcLang,
    regex: new RegExp(regexParts, "i"),
    slotNames,
    literalLength
  };
}

/**
 * Compile un jeu d'entrées de lexique et de langues.
 */
export function buildCompiledLexicon(
  entries: LexiconEntry[] = lexiconData as LexiconEntry[],
  languages: LanguageInfo[] = languagesData as LanguageInfo[]
): CompiledLexicon {
  const exactMap = new Map<LangCode, Map<string, LexiconEntry[]>>();
  const templatesByLang = new Map<LangCode, CompiledTemplate[]>();

  for (const entry of entries) {
    for (const [lang, rawText] of Object.entries(entry.text)) {
      if (!rawText) {
        continue;
      }
      const slots = extractSlots(rawText);
      if (slots.length === 0) {
        let langMap = exactMap.get(lang);
        if (!langMap) {
          langMap = new Map<string, LexiconEntry[]>();
          exactMap.set(lang, langMap);
        }
        const key = normalizeLexiconText(rawText);
        const list = langMap.get(key) ?? [];
        list.push(entry);
        langMap.set(key, list);
      } else {
        let list = templatesByLang.get(lang);
        if (!list) {
          list = [];
          templatesByLang.set(lang, list);
        }
        list.push(compileTemplate(entry, lang, rawText));
      }
    }
  }

  // Trier les gabarits par longueur littérale décroissante (plus spécifique d'abord), en préservant l'ordre initial en cas d'égalité
  for (const [lang, list] of templatesByLang.entries()) {
    const indexed = list.map((item, idx) => ({ item, idx }));
    indexed.sort((a, b) => {
      if (b.item.literalLength !== a.item.literalLength) {
        return b.item.literalLength - a.item.literalLength;
      }
      return a.idx - b.idx;
    });
    templatesByLang.set(
      lang,
      indexed.map((x) => x.item)
    );
  }

  return {
    entries,
    languages,
    exactMap,
    templatesByLang
  };
}

let defaultCompiledLexicon: CompiledLexicon | null = null;

/**
 * Retourne l'instance compilée par défaut du lexique embarqué.
 */
export function getDefaultLexicon(): CompiledLexicon {
  if (!defaultCompiledLexicon) {
    defaultCompiledLexicon = buildCompiledLexicon();
  }
  return defaultCompiledLexicon;
}

