/**
 * Rôle : Orchestration complète du pipeline de traduction d'un segment :
 *        détection -> protection (protector.ts) -> classification -> fournisseurs (Lexique -> Serveur Modèle Préconçu -> API Google Translate / LibreTranslate) -> vérification (verifier.ts) -> restauration.
 * Entrées : Texte brut à traduire et contexte d'exécution EngineContext.
 * Sorties : Promesse de TranslationResult { output, status, source, critical, reason }.
 * Limites : En cas d'échec de vérification d'un montant/jeton, retourne systématiquement le texte original ("failed-safe").
 */

import { TranslationCache } from "./cache.js";
import { isCriticalSegment } from "./classifier.js";
import { detect, detectWithShortWords } from "./detector.js";
import { protect, restore } from "./protector.js";
import { GoogleTranslateProvider } from "./providers/google-translate-provider.js";
import { LexiconProvider } from "./providers/lexicon-provider.js";
import { ModelServerProvider } from "./providers/model-server-provider.js";
import type {
  EngineContext,
  LangCode,
  TranslationProvider,
  TranslationResult
} from "./types.js";
import { verifyTranslation } from "./verifier.js";

const HAS_LETTERS_REGEX = /[a-zA-ZàâäæçéèêëîïôœùûüÿÀÂÄÆÇÉÈÊËÎÏÔŒÙÛÜŸ]/;
const PAGE_CONFIDENCE_THRESHOLD = 0.6;

export interface EngineOptions {
  lexiconProvider?: LexiconProvider;
  googleTranslateProvider?: GoogleTranslateProvider;
  modelServerProvider?: ModelServerProvider;
  enableLiveTranslation?: boolean;
  remoteProvider?: TranslationProvider;
  cacheSize?: number;
  onDebugLog?: (event: { type: string; reason?: string; critical?: boolean }) => void;
}

export class TranslationEngine {
  private readonly lexiconProvider: LexiconProvider;
  private readonly googleTranslateProvider?: GoogleTranslateProvider;
  private readonly modelServerProvider?: ModelServerProvider;
  private readonly enableLiveTranslation: boolean;
  private remoteProvider?: TranslationProvider;
  private readonly cache: TranslationCache;
  private readonly onDebugLog?: (event: { type: string; reason?: string; critical?: boolean }) => void;

  constructor(options: EngineOptions = {}) {
    this.lexiconProvider = options.lexiconProvider ?? new LexiconProvider();
    this.enableLiveTranslation = Boolean(options.enableLiveTranslation);
    this.googleTranslateProvider =
      options.googleTranslateProvider ??
      (this.enableLiveTranslation ? new GoogleTranslateProvider() : undefined);
    this.modelServerProvider =
      options.modelServerProvider ??
      (this.enableLiveTranslation ? new ModelServerProvider() : undefined);
    this.remoteProvider = options.remoteProvider;
    this.cache = new TranslationCache(options.cacheSize ?? 5000);
    this.onDebugLog = options.onDebugLog;
  }

  /**
   * Configure ou remplace le fournisseur distant optionnel.
   */
  public setRemoteProvider(provider?: TranslationProvider): void {
    this.remoteProvider = provider;
  }

  /**
   * Retourne le client du serveur de modèle préconçu pour mise à jour dynamique de sa configuration.
   */
  public getModelServerProvider(): ModelServerProvider | undefined {
    return this.modelServerProvider;
  }

  /**
   * Vide le cache mémoire LRU.
   */
  public clearCache(): void {
    this.cache.clear();
  }

  /**
   * Retourne le fournisseur lexique sous-jacent.
   */
  public getLexiconProvider(): LexiconProvider {
    return this.lexiconProvider;
  }

  /**
   * Traduit un segment unique en appliquant la politique de sécurité financière.
   */
  public async translateSegment(
    text: string,
    ctx: EngineContext = {}
  ): Promise<TranslationResult> {
    // 1. Texte vide ou uniquement constitué d'espaces
    if (!text || text.trim().length === 0) {
      return {
        output: text,
        status: "unchanged",
        source: "none",
        critical: false,
        reason: "empty-input"
      };
    }

    const leadingSpace = text.match(/^\s*/)?.[0] ?? "";
    const trailingSpace = text.match(/\s*$/)?.[0] ?? "";
    const trimmedText = text.trim();

    // Protection préliminaire pour identifier si le segment est purement numérique / valeur sensible isolée
    const protectedInput = protect(trimmedText);
    const textWithoutTokens = protectedInput.text
      .replace(/\{\{\d+\}\}/g, "")
      .replace(/<x\s+id="\d+"\s*\/>/g, "")
      .trim();

    if (!HAS_LETTERS_REGEX.test(textWithoutTokens)) {
      return {
        output: text,
        status: "unchanged",
        source: "none",
        critical: protectedInput.tokens.length > 0,
        reason: "numeric-or-symbol-only"
      };
    }

    // 2. Détecter la langue du segment (5.2), avec repli sur la langue de la page
    const segDetection = detect(trimmedText);
    let srcLang: LangCode | "unknown" = segDetection.lang;

    if (
      srcLang === "unknown" &&
      ctx.pageDetection &&
      ctx.pageDetection.lang !== "unknown" &&
      ctx.pageDetection.confidence >= PAGE_CONFIDENCE_THRESHOLD
    ) {
      srcLang = ctx.pageDetection.lang;
    }

    if (this.enableLiveTranslation) {
      if (segDetection.lang === "unknown") {
        const shortDet = detectWithShortWords(trimmedText);
        if (shortDet.lang !== "unknown") {
          srcLang = shortDet.lang;
        } else {
          // Pour tout libellé court ou dynamique de formulaire dont la langue n'est pas certaine localement,
          // utiliser "auto" afin que Google Translate / le serveur modèle détecte et traduise le champ sans jamais le sauter.
          srcLang = "auto";
        }
      }
    }

    // 4. Si langue détectée "unknown" (mode strict hors-ligne des tests unitaires) -> "unchanged"
    if (srcLang === "unknown") {
      return {
        output: text,
        status: "unchanged",
        source: "none",
        critical: false,
        reason: "unknown-language"
      };
    }

    // Détermination de la langue cible (Auto vs Manuel)
    const targetLang = this.resolveTargetLang(srcLang, ctx);

    // 3. Si langue détectée == langue cible -> "unchanged"
    if (srcLang === targetLang) {
      return {
        output: text,
        status: "unchanged",
        source: "none",
        critical: false,
        reason: "already-in-target-lang"
      };
    }

    // 5. Classification critique / libre (5.5)
    const effectiveLexSrc: LangCode =
      srcLang !== "auto"
        ? srcLang
        : ctx.pageDetection && ctx.pageDetection.lang !== "unknown"
          ? ctx.pageDetection.lang
          : targetLang === "en"
            ? "fr"
            : "en";
    const lexiconCrit =
      effectiveLexSrc !== targetLang &&
      this.lexiconProvider.isLexiconCritical(protectedInput.text, effectiveLexSrc);
    const critical = isCriticalSegment(trimmedText, protectedInput, lexiconCrit);

    // Consultation du cache mémoire LRU
    let translatedWithTokens = this.cache.get(srcLang, targetLang, protectedInput.text);
    let source: "lexicon" | "remote" | "none" =
      translatedWithTokens !== undefined ? "lexicon" : "none";

    // Étape A : Lexique financier validé (0 ms, déterministe)
    if (translatedWithTokens === undefined && effectiveLexSrc !== targetLang) {
      if (this.lexiconProvider.canTranslate(effectiveLexSrc, targetLang)) {
        const lexResult = await this.lexiconProvider.translate(
          protectedInput,
          effectiveLexSrc,
          targetLang,
          { critical }
        );
        if (lexResult !== null) {
          translatedWithTokens = lexResult;
          source = "lexicon";
          this.cache.set(srcLang, targetLang, protectedInput.text, lexResult);
        }
      }
    }

    // Étape B : Serveur hébergé exécutant votre modèle préconçu (prioritaire s'il est configuré et activé)
    if (
      translatedWithTokens === undefined &&
      this.enableLiveTranslation &&
      this.modelServerProvider &&
      this.modelServerProvider.canTranslate(srcLang, targetLang)
    ) {
      try {
        const modelOut = await this.modelServerProvider.translate(
          protectedInput,
          srcLang,
          targetLang,
          { critical }
        );
        if (modelOut !== null) {
          translatedWithTokens = modelOut;
          source = "remote";
          this.cache.set(srcLang, targetLang, protectedInput.text, modelOut);
        }
      } catch {
        this.logDebug(ctx, { type: "model-server-error", reason: "provider-exception", critical });
      }
    }

    // Étape C : API Google Translate pour traduire l'intégralité de la page (tous les <div>, <p>, <span>, etc.)
    if (
      translatedWithTokens === undefined &&
      this.enableLiveTranslation &&
      this.googleTranslateProvider &&
      this.googleTranslateProvider.canTranslate(srcLang, targetLang)
    ) {
      try {
        const googleOut = await this.googleTranslateProvider.translate(
          protectedInput,
          srcLang,
          targetLang,
          { critical }
        );
        if (googleOut !== null) {
          translatedWithTokens = googleOut;
          source = "remote";
          this.cache.set(srcLang, targetLang, protectedInput.text, googleOut);
        }
      } catch {
        this.logDebug(ctx, { type: "google-translate-error", reason: "provider-exception", critical });
      }
    }

    // Si aucun résultat jusqu'ici : appliquer la politique 5.5
    if (translatedWithTokens === undefined) {
      if (critical) {
        this.logDebug(ctx, { type: "fallback", reason: "no-lexicon-match", critical: true });
        return {
          output: text,
          status: "failed-safe",
          source: "none",
          critical: true,
          reason: "no-lexicon-match"
        };
      }

      // Segment LIBRE : tenter le fournisseur distant LibreTranslate s'il est activé explicitement
      if (
        ctx.remoteEnabled &&
        this.remoteProvider &&
        this.remoteProvider.canTranslate(srcLang, targetLang)
      ) {
        try {
          const remoteOut = await this.remoteProvider.translate(
            protectedInput,
            srcLang,
            targetLang,
            { critical: false }
          );
          if (remoteOut !== null) {
            translatedWithTokens = remoteOut;
            source = "remote";
          }
        } catch {
          this.logDebug(ctx, { type: "remote-error", reason: "provider-exception", critical: false });
        }
      }

      if (translatedWithTokens === undefined) {
        return {
          output: text,
          status: "unchanged",
          source: "none",
          critical: false,
          reason: "no-lexicon-match"
        };
      }
    }

    // 6. Restauration des jetons et vérification d'intégrité (5.6)
    const restoredCore = restore(translatedWithTokens, protectedInput.tokens);

    // Si l'API de traduction retourne exactement le même texte (ex. nom propre, marque ou déjà dans la langue cible)
    if (restoredCore.trim() === trimmedText) {
      return {
        output: text,
        status: "unchanged",
        source: "none",
        critical,
        reason: "already-in-target-lang"
      };
    }

    const verification = verifyTranslation(
      trimmedText,
      protectedInput,
      translatedWithTokens,
      restoredCore
    );

    if (!verification.valid) {
      this.logDebug(ctx, {
        type: "verification-failed",
        reason: verification.reason,
        critical
      });
      return {
        output: text,
        status: "failed-safe",
        source,
        critical,
        reason: verification.reason
      };
    }

    return {
      output: `${leadingSpace}${restoredCore}${trailingSpace}`,
      status: "translated",
      source,
      critical
    };
  }

  private resolveTargetLang(srcLang: LangCode, ctx: EngineContext): LangCode {
    if (ctx.mode === "manual" && ctx.targetLang) {
      return ctx.targetLang;
    }
    if (ctx.targetLang && ctx.mode !== "auto") {
      return ctx.targetLang;
    }
    const baseLang =
      ctx.pageDetection &&
      ctx.pageDetection.lang !== "unknown" &&
      ctx.pageDetection.confidence >= PAGE_CONFIDENCE_THRESHOLD
        ? ctx.pageDetection.lang
        : srcLang !== "auto"
          ? srcLang
          : "fr";
    return baseLang === "fr" ? "en" : "fr";
  }

  private logDebug(
    ctx: EngineContext,
    event: { type: string; reason?: string; critical?: boolean }
  ): void {
    if (ctx.debug && this.onDebugLog) {
      this.onDebugLog(event);
    }
  }
}
