/**
 * Rôle : Fournisseur de traduction distant optionnel (compatible LibreTranslate), strictement réservé aux segments NON critiques et désactivé par défaut (Section 5.5).
 * Entrées : Texte DÉJÀ PROTÉGÉ (Protected.text avec jetons {{n}}, sans aucune valeur sensible réelle), langue source, langue cible et contexte.
 * Sorties : Chaîne traduite contenant les jetons {{n}}, ou null en cas d'erreur, de délai dépassé (4 s) ou de segment critique.
 * Limites : Ne transmet jamais les valeurs de Protected.tokens ; délègue la requête HTTP au script d'arrière-plan via browser.runtime.sendMessage pour éviter les restrictions CORS/CSP de la page hôte.
 */

import { safeRuntimeSendMessage } from "../../shared/ext.js";
import type { RemoteTranslateResponse } from "../../shared/messages.js";
import type { LangCode, Protected, TranslationProvider } from "../types.js";

const DEFAULT_TIMEOUT_MS = 4000;
const MAX_RETRIES = 1;

export class RemoteProvider implements TranslationProvider {
  public readonly id = "remote";
  private remoteUrl: string;
  private readonly timeoutMs: number;

  constructor(remoteUrl = "", timeoutMs = DEFAULT_TIMEOUT_MS) {
    this.remoteUrl = remoteUrl.trim();
    this.timeoutMs = timeoutMs;
  }

  public setRemoteUrl(url: string): void {
    this.remoteUrl = url.trim();
  }

  public getRemoteUrl(): string {
    return this.remoteUrl;
  }

  public canTranslate(src: LangCode, tgt: LangCode): boolean {
    if (!this.remoteUrl || src === tgt) {
      return false;
    }
    return /^https?:\/\//i.test(this.remoteUrl);
  }

  public async translate(
    input: Protected,
    src: LangCode,
    tgt: LangCode,
    ctx: { critical: boolean }
  ): Promise<string | null> {
    // Barrière de sécurité absolue : aucun segment critique ne peut être envoyé à un service distant
    if (ctx.critical || !this.canTranslate(src, tgt)) {
      return null;
    }

    for (let attempt = 0; attempt <= MAX_RETRIES; attempt += 1) {
      try {
        const result = await this.sendWithTimeout(input.text, src, tgt);
        if (result !== null) {
          return result;
        }
      } catch {
        // Ignorer et tenter le retry unique si disponible
      }
    }

    return null;
  }

  private async sendWithTimeout(
    protectedText: string,
    src: LangCode,
    tgt: LangCode
  ): Promise<string | null> {
    const timeoutPromise = new Promise<null>((resolve) => {
      setTimeout(() => resolve(null), this.timeoutMs);
    });

    const requestPromise = (async (): Promise<string | null> => {
      const response = await safeRuntimeSendMessage<RemoteTranslateResponse>({
        type: "REMOTE_TRANSLATE",
        payload: {
          protectedText,
          src,
          tgt,
          remoteUrl: this.remoteUrl
        }
      });

      if (response && response.ok && typeof response.translatedText === "string") {
        return response.translatedText;
      }
      return null;
    })();

    return Promise.race([requestPromise, timeoutPromise]);
  }
}

