/**
 * Rôle : Détection heuristique locale (sans réseau) de la langue (FR / EN) d'un segment ou d'une page complète (y compris SPA React, Next.js, Angular).
 * Entrées : Chaîne de texte brut (pour detect / detectWithShortWords) ou liste de textes visibles + attribut lang HTML (pour detectPageLanguage).
 * Sorties : Objet Detection { lang: LangCode | "unknown", confidence: number (0..1) }.
 * Limites : detect() exige >= 3 mots conformément à la spécification 5.2 ; detectWithShortWords() et detectPageLanguage() exploitent également les libellés courts d'interface (1 à 2 mots) afin de détecter correctement les tableaux de bord et SPA.
 */

import type { Detection, LangCode } from "./types.js";

export interface LanguageDetector {
  detect(text: string): Detection;
}

