/**
 * Acronymes monétaires et techniques neutres ignorés lors du comptage des mots linguistiques.
 */
const NEUTRAL_TOKENS = new Set<string>([
  "fcfa", "cfa", "xaf", "xof", "eur", "usd", "id", "iban", "ref", "tx", "am", "pm", "ok"
]);

const FR_DIACRITIC_REGEX = /[éèêëàâçùûüîïôœæ]/gi;
const FR_CONTRACTION_REGEX = /\b(?:l|d|qu|n|s|c|j|m|t)['’‘`][a-zàâäæçéèêëîïôœùûüÿ]/gi;
const EN_CONTRACTION_REGEX = /\b(?:[a-z]+['’‘`]s|don['’‘`]t|can['’‘`]t|won['’‘`]t|isn['’‘`]t|aren['’‘`]t|you['’‘`]re|we['’‘`]re|it['’‘`]s)\b/gi;

const DEFAULT_MARGIN_THRESHOLD = 0.15;
const MIN_WORDS_FOR_SEGMENT = 3;

/**
 * Extrait les mots alphabétiques utiles d'un texte après suppression des jetons et nombres.
 */
export function extractWords(text: string): string[] {
  const withoutPlaceholders = text
    .replace(/\{\{\d+\}\}/g, " ")
    .replace(/<x\s+id="\d+"\s*\/>/gi, " ")
    .toLowerCase();

  const normalizedPossessive = withoutPlaceholders.replace(/([a-z]{2,})['’‘`]s\b/gi, "$1");

  const rawWords = normalizedPossessive.match(/[a-zàâäæçéèêëîïôœùûüÿ]+/gi) ?? [];
  return rawWords.filter((w) => {
    if (NEUTRAL_TOKENS.has(w)) {
      return false;
    }
    if (w.length === 1 && w !== "a" && w !== "à" && w !== "y" && w !== "i") {
      return false;
    }
    return true;
  });
}

/**
 * Calcule les scores FR et EN sur un texte quelle que soit sa longueur (utilisé en interne et pour les libellés courts en mode page).
 */
export function computeLanguageScores(text: string): {
  words: string[];
  scoreFr: number;
  scoreEn: number;
} {
  const words = extractWords(text);
  const wordCount = words.length;
  if (wordCount === 0) {
    return { words, scoreFr: 0, scoreEn: 0 };
  }

  let frHits = 0;
  let enHits = 0;

  for (const word of words) {
    const cleanWord = word.toLowerCase();
    if (FR_STOPWORDS.has(cleanWord)) {
      frHits += 1;
    }
    if (EN_STOPWORDS.has(cleanWord)) {
      enHits += 1;
    }
  }

  const diacriticMatches = text.match(FR_DIACRITIC_REGEX)?.length ?? 0;
  const frContractions = text.match(FR_CONTRACTION_REGEX)?.length ?? 0;
  const enContractions = text.match(EN_CONTRACTION_REGEX)?.length ?? 0;

  const frBonus = Math.min(0.4, diacriticMatches * 0.1 + frContractions * 0.14);
  const enBonus = Math.min(0.3, enContractions * 0.14);

  return {
    words,
    scoreFr: frHits / wordCount + frBonus,
    scoreEn: enHits / wordCount + enBonus
  };
}

/**
 * Détecteur heuristique FR / EN standard (Section 5.2 : retourne unknown si < 3 mots).
 */
export class HeuristicDetector implements LanguageDetector {
  private readonly threshold: number;

  constructor(threshold = DEFAULT_MARGIN_THRESHOLD) {
    this.threshold = threshold;
  }

  public detect(text: string): Detection {
    if (!text || typeof text !== "string") {
      return { lang: "unknown", confidence: 0 };
    }

    const { words, scoreFr, scoreEn } = computeLanguageScores(text);
    if (words.length < MIN_WORDS_FOR_SEGMENT) {
      return { lang: "unknown", confidence: 0 };
    }

    const maxScore = Math.max(scoreFr, scoreEn);
    const margin = Math.abs(scoreFr - scoreEn);

    if (maxScore === 0 || margin < this.threshold) {
      return {
        lang: "unknown",
        confidence: Number(Math.min(0.4, margin).toFixed(3))
      };
    }

    const bestLang: LangCode = scoreFr > scoreEn ? "fr" : "en";
    const rawConfidence = Math.min(
      1,
      (margin / Math.max(0.4, maxScore)) * 0.65 + margin * 0.7
    );
    const confidence = Number(Math.max(0.15, Math.min(1, rawConfidence)).toFixed(3));

    return { lang: bestLang, confidence };
  }
}

let activeDetector: LanguageDetector = new HeuristicDetector();

/**
 * Permet de brancher un détecteur externe derrière la même interface.
 */
export function setLanguageDetector(detector: LanguageDetector): void {
  activeDetector = detector;
}

/**
 * Détecte la langue d'un segment de texte (>= 3 mots).
 */
export function detect(text: string): Detection {
  return activeDetector.detect(text);
}

/**
 * Détecte la langue d'un segment même court (1 à 2 mots) lorsqu'il contient des mots-outils ou diacritiques non ambigus.
 */
export function detectWithShortWords(text: string): Detection {
  const std = detect(text);
  if (std.lang !== "unknown") {
    return std;
  }
  const { words, scoreFr, scoreEn } = computeLanguageScores(text);
  if (words.length === 0) {
    return { lang: "unknown", confidence: 0 };
  }
  const margin = Math.abs(scoreFr - scoreEn);
  if (margin < 0.25) {
    return { lang: "unknown", confidence: 0 };
  }
  return {
    lang: scoreFr > scoreEn ? "fr" : "en",
    confidence: Number(Math.min(0.9, margin).toFixed(3))
  };
}

/**
 * Détecte la langue dominante d'une page à partir d'un échantillon de nœuds texte visibles
 * (phrases longues ET libellés d'interface courts, fréquents dans les SPA React/Next.js/Angular).
 * L'attribut <html lang="..."> n'a qu'un poids minime pour ne pas être trompé par <html lang="en"> laissé par défaut dans les templates React/Next.js/Angular.
 */
export function detectPageLanguage(texts: string[], htmlLang?: string): Detection {
  const weights: Record<string, number> = { fr: 0, en: 0 };
  let totalWeight = 0;
  let sampled = 0;

  for (const raw of texts) {
    if (sampled >= 400) {
      break;
    }
    const { words, scoreFr, scoreEn } = computeLanguageScores(raw);
    if (words.length === 0) {
      continue;
    }

    sampled += 1;
    const margin = Math.abs(scoreFr - scoreEn);
    if (margin < 0.15) {
      continue;
    }

    const lang: LangCode = scoreFr > scoreEn ? "fr" : "en";
    // Les phrases de >= 3 mots pèsent davantage que les libellés de 1-2 mots
    const weight = words.length >= 3 ? words.length * 1.5 : words.length * 0.8;
    const confidence = Math.min(1, margin + 0.3);
    totalWeight += weight;
    weights[lang] = (weights[lang] ?? 0) + weight * confidence;
  }

  const textWeight = totalWeight;

  // Indice secondaire document.documentElement.lang : uniquement si très peu de texte sur la page
  if (htmlLang && textWeight < 4) {
    const cleanHtmlLang = htmlLang.trim().toLowerCase().slice(0, 2);
    if (cleanHtmlLang === "fr" || cleanHtmlLang === "en") {
      const hintWeight = textWeight === 0 ? 1.5 : 0.5;
      weights[cleanHtmlLang] = (weights[cleanHtmlLang] ?? 0) + hintWeight;
      totalWeight += hintWeight;
    }
  }

  if (totalWeight === 0) {
    return { lang: "unknown", confidence: 0 };
  }

  const frScore = (weights.fr ?? 0) / totalWeight;
  const enScore = (weights.en ?? 0) / totalWeight;
  const maxScore = Math.max(frScore, enScore);
  const margin = Math.abs(frScore - enScore);

  if (maxScore === 0 || margin < 0.08) {
    return { lang: "unknown", confidence: Number(margin.toFixed(3)) };
  }

  const bestLang: LangCode = frScore > enScore ? "fr" : "en";
  // Si la détection repose uniquement ou principalement sur <html lang="..."> sans texte réel suffisant,
  // plafonner la confiance à 0.55 afin qu'elle soit recalculée dès que la SPA (React/Next.js/Angular) monte son DOM.
  if (textWeight < 3) {
    return { lang: bestLang, confidence: 0.55 };
  }

  const directionalRatio =
    Math.abs((weights.fr ?? 0) - (weights.en ?? 0)) /
    Math.max(0.5, (weights.fr ?? 0) + (weights.en ?? 0));
  const confidence = Number(
    Math.min(1, Math.max(0.65, directionalRatio * 0.8 + Math.min(0.2, maxScore * 0.4))).toFixed(3)
  );

  return { lang: bestLang, confidence };
}
